def _copy_board(board):
    try:
        rows = [list(row) for row in board]
    except TypeError as exc:
        raise ValueError("board must be an iterable of rows") from exc
    if not rows or not rows[0]:
        raise ValueError("board must be nonempty")
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError("board must be rectangular")
    if any(
        isinstance(cell, bool)
        or not isinstance(cell, int)
        or cell not in (0, 1)
        for row in rows
        for cell in row
    ):
        raise ValueError("cells must be 0 or 1")
    return [row[:] for row in rows]


def evolve(board, steps=1, wrap=False):
    current = _copy_board(board)
    if isinstance(steps, bool) or not isinstance(steps, int) or steps < 0:
        raise ValueError("steps must be a nonnegative integer")
    if not isinstance(wrap, bool):
        raise ValueError("wrap must be boolean")

    height = len(current)
    width = len(current[0])

    for _ in range(steps):
        following = [[0] * width for _ in range(height)]
        for row in range(height):
            for column in range(width):
                neighbors = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr = row + dr
                        nc = column + dc
                        if wrap:
                            nr %= height
                            nc %= width
                            neighbors += current[nr][nc]
                        elif 0 <= nr < height and 0 <= nc < width:
                            neighbors += current[nr][nc]
                following[row][column] = int(
                    neighbors == 3
                    or (current[row][column] == 1 and neighbors == 2)
                )
        current = following

    return current

